//! paintio.library's functions: Paint's projects and pictures read from
//! and written to files. It is Paint's own, in Paint's drawer, and Paint
//! opens it by its path (sdk.paintio.PAINTIOPATH). A call that can fail
//! answers 0, or a dos error code that Fault puts into words.
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/paintio_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const paintio = @import("../libs/paintio/paintio.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "paintio.library";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const LoadProject = libraries.lvo(4);
    pub const SaveProject = libraries.lvo(5);
    pub const SavePicture = libraries.lvo(6);
    pub const FreeProject = libraries.lvo(7);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const LoadProject = *const fn (*PaintIOBase, [*:0]const u8, *paintio.Project) callconv(.c) i32;
    pub const SaveProject = *const fn (*PaintIOBase, [*:0]const u8, *const paintio.Project) callconv(.c) i32;
    pub const SavePicture = *const fn (*PaintIOBase, [*:0]const u8, [*]const u32, u32, u32, u32) callconv(.c) i32;
    pub const FreeProject = *const fn (*PaintIOBase, *paintio.Project) callconv(.c) void;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const PaintIOBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *PaintIOBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// A project, or a picture datatypes reads, as a project.
    pub fn LoadProject(self: *PaintIOBase, name: [*:0]const u8, project: *paintio.Project) i32 {
        return libraries.call(self, LVO.LoadProject, Fn.LoadProject, .{ name, project });
    }

    /// The project written as a FORM PNTG.
    pub fn SaveProject(self: *PaintIOBase, name: [*:0]const u8, project: *const paintio.Project) i32 {
        return libraries.call(self, LVO.SaveProject, Fn.SaveProject, .{ name, project });
    }

    /// Pixels written as a picture: PNG or ILBM (PIOFORMAT_*).
    pub fn SavePicture(self: *PaintIOBase, name: [*:0]const u8, pixels: [*]const u32, width: u32, height: u32, format: u32) i32 {
        return libraries.call(self, LVO.SavePicture, Fn.SavePicture, .{ name, pixels, width, height, format });
    }

    /// What LoadProject allocated given back.
    pub fn FreeProject(self: *PaintIOBase, project: *paintio.Project) void {
        return libraries.call(self, LVO.FreeProject, Fn.FreeProject, .{project});
    }
};
